CREATE TABLE act_role (
  code text PRIMARY KEY,
  label text NOT NULL,
  definition text
);
INSERT INTO act_role (code, label, definition) VALUES ('Initiator', 'Initiator', 'The person whose request, or whose standing directive, is why the act happens; an agent is never one.');
INSERT INTO act_role (code, label, definition) VALUES ('Preparer', 'Preparer', 'The actor that made the artifact of the act: a document, a change, a test or a plan. Any kind of actor can prepare.');
INSERT INTO act_role (code, label, definition) VALUES ('Assistant', 'Assistant', 'An agent or a system that operated a tool during a step of the act, under a directive and a tasking.');
INSERT INTO act_role (code, label, definition) VALUES ('Executor', 'Executor', 'The person, or the validated mechanism, that carried the step out.');
INSERT INTO act_role (code, label, definition) VALUES ('Reviewer', 'Reviewer', 'A person who read the artifact and signed that review; for a regulated act, not the person who prepared it.');
INSERT INTO act_role (code, label, definition) VALUES ('Approver', 'Approver', 'A person whose signature, with a key of their own, bound the plan hash of the act.');

CREATE TABLE act_actor_kind (
  code text PRIMARY KEY,
  label text NOT NULL,
  definition text
);
INSERT INTO act_actor_kind (code, label, definition) VALUES ('Person', 'Person', 'A human being, who can be accountable and can sign.');
INSERT INTO act_actor_kind (code, label, definition) VALUES ('System', 'System', 'A deterministic mechanism that a person validated: the engine, a typed verb, a pipeline.');
INSERT INTO act_actor_kind (code, label, definition) VALUES ('Agent', 'Agent', 'An AI agent: a model run under instructions with tools. It is instructed, not accountable, and what it makes is a draft until a person or a validated mechanism clears it.');

CREATE TABLE act_tasking_level (
  code text PRIMARY KEY,
  label text NOT NULL,
  definition text
);
INSERT INTO act_tasking_level (code, label, definition) VALUES ('T0Suggest', 'T0, suggest', 'The agent only suggests; nothing it makes enters a record.');
INSERT INTO act_tasking_level (code, label, definition) VALUES ('T1Prepare', 'T1, prepare', 'The agent prepares drafts in a branch or a sandbox; a person reviews them before they enter a record.');
INSERT INTO act_tasking_level (code, label, definition) VALUES ('T2AssistExecution', 'T2, assist execution', 'The agent assists a step whose plan hash a person approved for each step; the engine carries it out.');
INSERT INTO act_tasking_level (code, label, definition) VALUES ('T3AssistReversible', 'T3, assist reversible steps', 'The agent assists reversible, low risk steps under a standing directive and a current qualification; the owner of the directive stays the initiator and the engine stays the executor.');

