INSERT INTO act_signature_meaning (code, label, definition) VALUES ('Review', 'Review', 'The signer read the record and found it fit for its purpose.');
INSERT INTO act_signature_meaning (code, label, definition) VALUES ('Approval', 'Approval', 'The signer approved the record or the plan it names, by its hash.');
INSERT INTO act_signature_meaning (code, label, definition) VALUES ('Responsibility', 'Responsibility', 'The signer takes responsibility for what the record states.');
INSERT INTO act_signature_meaning (code, label, definition) VALUES ('Authorship', 'Authorship', 'The signer made the record.');
